# Nested check: is "compact beats all-features" an artefact of selecting features on the same folds?
import sys; sys.path.insert(0,'scratch')
import lab, numpy as np, pandas as pd
from sklearn.metrics import roc_auc_score
from sklearn.model_selection import StratifiedGroupKFold
tr=lab.tr; X=tr[lab.FEATS]; y=tr.deteriorated.to_numpy(); g=tr.utility_id.to_numpy()
ALL=('raw','rel','aux','cat','tlog','round','order','dq')
def fitpred(a,b,keep,seed=42):
    mod=lab.load('scratch/train_flexible.py'); mod.CFG.update({'state':'none','groups':ALL,'keep':keep})
    st=mod.fit(X.iloc[a].reset_index(drop=True),y[a],seed=seed,threads=5); P=mod.prepare(st,X.iloc[b].reset_index(drop=True)); return st['model'],P
res={'all':[], 'nested top13':[], 'fixed compact13':[]}; picks=[]
T=('lcaidi','lmed','lcustmin','mean_med','gap','l2','l3','lcust','lint','med_caidi','lsaifim','t_up','t_down')
for rep in range(2):
    oo={k:np.zeros(len(y)) for k in res}
    for a,b in StratifiedGroupKFold(5,shuffle=True,random_state=100+rep).split(X,y,g):
        rng=np.random.RandomState(rep); drops={}
        for ia,ib in StratifiedGroupKFold(4,shuffle=True,random_state=rep).split(X.iloc[a],y[a],g[a]):
            m,P=fitpred(a[ia],a[ib],None); b0=roc_auc_score(y[a[ib]],m.predict_proba(P)[:,1])
            for c in P.columns:
                for _ in range(2):
                    Q=P.copy(); Q[c]=rng.permutation(Q[c].to_numpy()); drops.setdefault(c,[]).append(b0-roc_auc_score(y[a[ib]],m.predict_proba(Q)[:,1]))
        top=tuple(sorted(drops,key=lambda c:-np.mean(drops[c]))[:13]); picks.append(top)
        for k,keep in (('all',None),('nested top13',top),('fixed compact13',T)):
            m,P=fitpred(a,b,keep); oo[k][b]=m.predict_proba(P)[:,1]
    for k in res: res[k].append(roc_auc_score(y,oo[k]))
for k,v in res.items(): print('%-16s gcv %.4f'%(k,np.mean(v)), np.round(v,4))
from collections import Counter
c=Counter(f for p in picks for f in p); print('selection frequency over 10 outer folds:',c.most_common(22))
