"""Diagnostic: the low-median-SAIDI effect decays by cohort. Does flooring/dampening the level features help out-of-period?"""
import sys; sys.path.insert(0,'scratch')
from dev import *
from sklearn.model_selection import StratifiedGroupKFold
base_prep=T.prepare
folds=[list(StratifiedGroupKFold(5,shuffle=True,random_state=100+r).split(Xtr,ytr,tr.utility_id)) for r in range(4)]
def make(floor=None,drop=()):
    def prep(state,X):
        f=base_prep(state,X)
        if floor is not None:
            m=np.maximum(f['med'].to_numpy(),floor); f['med']=m; f['cust_minutes']=np.log1p(m*10**f['logcust'].to_numpy())
        return f.drop(columns=[c for c in drop if c in f.columns])
    return prep
def run_(name,prep):
    T.prepare=prep; o=[]
    for r in range(4):
        p=np.zeros(len(ytr))
        for a,b in folds[r]:
            s=T.fit(Xtr.iloc[a].copy(),ytr[a],seed=42,threads=5); p[b]=T.predict(s,Xtr.iloc[b])
        o.append(roc_auc_score(ytr,p))
